-- Story #326: free-form venue amenity tags
-- Tags such as "parking" or "wheelchair accessible", and the links from venues to their tags.
-- Idempotent: safe to re-run. No data is seeded; tags are created as owners and staff add them.
--
-- Run against the right database first and check which server you are on:
--   SELECT current_database(), inet_server_addr();

BEGIN;

CREATE TABLE IF NOT EXISTS public."VenueTags" (
    "VenueTagID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(30) NOT NULL
);

-- The API stores names trimmed, lowercase and with single spaces, so one row per tag.
CREATE UNIQUE INDEX IF NOT EXISTS "IX_VenueTags_Name"
    ON public."VenueTags" ("Name");

CREATE TABLE IF NOT EXISTS public."Linker_VenueToTag" (
    "Linker_VenueToTagID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "VenueID" integer NOT NULL,
    "VenueTagID" integer NOT NULL
);

-- A venue has a given tag at most once.
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Linker_VenueToTag_VenueID_VenueTagID"
    ON public."Linker_VenueToTag" ("VenueID", "VenueTagID");

-- Used when filtering venues by tag and when counting how many venues use a tag.
CREATE INDEX IF NOT EXISTS "IX_Linker_VenueToTag_VenueTagID"
    ON public."Linker_VenueToTag" ("VenueTagID");

DO $migration$
BEGIN
    -- Links are removed together with their venue.
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'FK_Linker_VenueToTag_Venues_VenueID' AND conrelid = 'public."Linker_VenueToTag"'::regclass
    ) THEN
        ALTER TABLE public."Linker_VenueToTag"
            ADD CONSTRAINT "FK_Linker_VenueToTag_Venues_VenueID"
            FOREIGN KEY ("VenueID") REFERENCES public."Venues" ("VenueID") ON DELETE CASCADE;
    END IF;

    -- Staff can remove a tag, which takes it off every venue.
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'FK_Linker_VenueToTag_VenueTags_VenueTagID' AND conrelid = 'public."Linker_VenueToTag"'::regclass
    ) THEN
        ALTER TABLE public."Linker_VenueToTag"
            ADD CONSTRAINT "FK_Linker_VenueToTag_VenueTags_VenueTagID"
            FOREIGN KEY ("VenueTagID") REFERENCES public."VenueTags" ("VenueTagID") ON DELETE CASCADE;
    END IF;
END
$migration$;

COMMIT;
